class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w)); adj[v].append((u, w))
        par = [-1] * n; order = []; st = [0]; vis = [False] * n; vis[0] = True
        while st:
            u = st.pop(); order.append(u)
            for v, w in adj[u]:
                if not vis[v]:
                    vis[v] = True; par[v] = u; st.append(v)
        g = [0] * n
        ans = 0
        for u in reversed(order):
            gains = sorted((w + g[v] for v, w in adj[u] if v != par[u]), reverse=True)
            g[u] = sum(gains[:k - 1])
            if u == 0: ans = sum(gains[:k])
        return ans

