class Solution {
public:
    long long maximizeSumOfWeights(vector<vector<int>>& edges, int k) {
        int n = edges.size() + 1;
        vector<vector<pair<int,int>>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
            adj[e[1]].push_back({e[0], e[2]});
        }
        vector<int> par(n, -1), order; vector<bool> vis(n, false);
        vector<int> st{0}; vis[0] = true;
        while (!st.empty()) {
            int u = st.back(); st.pop_back(); order.push_back(u);
            for (auto [v, w] : adj[u]) if (!vis[v]) { vis[v] = true; par[v] = u; st.push_back(v); }
        }
        vector<long long> g(n, 0);
        long long ans = 0;
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            vector<long long> gains;
            for (auto [v, w] : adj[u]) if (v != par[u]) gains.push_back(w + g[v]);
            sort(gains.rbegin(), gains.rend());
            g[u] = 0;
            for (int t = 0; t < min((int)gains.size(), k - 1); t++) g[u] += gains[t];
            if (u == 0) {
                ans = 0;
                for (int t = 0; t < min((int)gains.size(), k); t++) ans += gains[t];
            }
        }
        return ans;
    }
};

