class Solution {
    public long maximizeSumOfWeights(List<List<Integer>> edges, int k) {
        int n = edges.size() + 1;
        List<List<long[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (List<Integer> e : edges) {
            adj.get(e.get(0)).add(new long[]{e.get(1), e.get(2)});
            adj.get(e.get(1)).add(new long[]{e.get(0), e.get(2)});
        }
        int[] par = new int[n]; Arrays.fill(par, -1);
        List<Integer> order = new ArrayList<>();
        boolean[] vis = new boolean[n]; Deque<Integer> st = new ArrayDeque<>(List.of(0)); vis[0] = true;
        while (!st.isEmpty()) {
            int u = st.pop(); order.add(u);
            for (long[] vw : adj.get(u)) {
                int v = (int) vw[0];
                if (!vis[v]) { vis[v] = true; par[v] = u; st.push(v); }
            }
        }
        long[] g = new long[n]; long ans = 0;
        for (int i = n - 1; i >= 0; i--) {
            int u = order.get(i);
            List<Long> gains = new ArrayList<>();
            for (long[] vw : adj.get(u)) if ((int) vw[0] != par[u]) gains.add(vw[1] + g[(int) vw[0]]);
            Collections.sort(gains, Collections.reverseOrder());
            g[u] = 0;
            for (int t = 0; t < Math.min(gains.size(), k - 1); t++) g[u] += gains.get(t);
            if (u == 0) { ans = 0; for (int t = 0; t < Math.min(gains.size(), k); t++) ans += gains.get(t); }
        }
        return ans;
    }
}

