var maximizeSumOfWeights = function(edges, k) {
    const n = edges.length + 1;
    const adj = Array.from({length: n}, () => []);
    for (const [u, v, w] of edges) { adj[u].push([v, w]); adj[v].push([u, w]); }
    const par = Array(n).fill(-1), order = [], vis = Array(n).fill(false);
    const st = [0]; vis[0] = true;
    while (st.length) {
        const u = st.pop(); order.push(u);
        for (const [v, w] of adj[u]) if (!vis[v]) { vis[v] = true; par[v] = u; st.push(v); }
    }
    const g = Array(n).fill(0);
    let ans = 0;
    for (let i = n - 1; i >= 0; i--) {
        const u = order[i];
        const gains = adj[u].filter(([v]) => v !== par[u]).map(([v, w]) => w + g[v]).sort((a, b) => b - a);
        g[u] = gains.slice(0, k - 1).reduce((a, b) => a + b, 0);
        if (u === 0) ans = gains.slice(0, k).reduce((a, b) => a + b, 0);
    }
    return ans;
};
